class Solution {
    long long MOD = 1e9 + 7;
    vector<long long> tree_sum, tree_sq, lazy;
    void apply(int node, int l, int r, long long v) {
        long long len = r - l + 1;
        tree_sq[node] = (tree_sq[node] + 2 * v * tree_sum[node] + len * (v % MOD) % MOD * v) % MOD;
        tree_sum[node] = (tree_sum[node] + len * v) % MOD;
        lazy[node] = (lazy[node] + v) % MOD;
    }
    void push_down(int node, int l, int r) {
        if (lazy[node] != 0) {
            int mid = l + (r - l) / 2;
            apply(2 * node, l, mid, lazy[node]);
            apply(2 * node + 1, mid + 1, r, lazy[node]);
            lazy[node] = 0;
        }
    }
    void update(int node, int l, int r, int ql, int qr, long long v) {
        if (ql <= l && r <= qr) {
            apply(node, l, r, v);
            return;
        }
        push_down(node, l, r);
        int mid = l + (r - l) / 2;
        if (ql <= mid) update(2 * node, l, mid, ql, qr, v);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr, v);
        tree_sum[node] = (tree_sum[2 * node] + tree_sum[2 * node + 1]) % MOD;
        tree_sq[node] = (tree_sq[2 * node] + tree_sq[2 * node + 1]) % MOD;
    }
public:
    int sumCounts(vector<int>& nums) {
        int n = nums.size();
        tree_sum.assign(4 * n, 0);
        tree_sq.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        unordered_map<int, int> last_seen;
        long long total = 0;
        for (int r = 0; r < n; r++) {
            int l = last_seen.count(nums[r]) ? last_seen[nums[r]] + 1 : 0;
            update(1, 0, n - 1, l, r, 1);
            total = (total + tree_sq[1]) % MOD;
            last_seen[nums[r]] = r;
        }
        return total;
    }
};

