    void update(int node, int l, int r, int ql, int qr, long v) {
        if (ql <= l && r <= qr) {
            apply(node, l, r, v);
            return;
        }
        push_down(node, l, r);
        int mid = l + (r - l) / 2;
        if (ql <= mid) update(2 * node, l, mid, ql, qr, v);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr, v);
        tree_sum[node] = (tree_sum[2 * node] + tree_sum[2 * node + 1]) % MOD;
        tree_sq[node] = (tree_sq[2 * node] + tree_sq[2 * node + 1]) % MOD;
    }
    public int sumCounts(int[] nums) {
        int n = nums.length;
        tree_sum = new long[4 * n];
        tree_sq = new long[4 * n];
        lazy = new long[4 * n];
        Map<Integer, Integer> last_seen = new HashMap<>();
        long total = 0;
        for (int r = 0; r < n; r++) {
            int l = last_seen.getOrDefault(nums[r], -1) + 1;
            update(1, 0, n - 1, l, r, 1);
