var sumCounts = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const tree_sum = new BigInt64Array(4 * n);
    const tree_sq = new BigInt64Array(4 * n);
    const lazy = new BigInt64Array(4 * n);

    function apply(node, l, r, v) {
        const len = BigInt(r - l + 1);
        tree_sq[node] = (tree_sq[node] + 2n * v * tree_sum[node] + len * (v % MOD) * v) % MOD;
        tree_sum[node] = (tree_sum[node] + len * v) % MOD;
        lazy[node] = (lazy[node] + v) % MOD;
    }
    function push_down(node, l, r) {
        if (lazy[node] !== 0n) {
            const mid = Math.floor((l + r) / 2);
            apply(2 * node, l, mid, lazy[node]);
            apply(2 * node + 1, mid + 1, r, lazy[node]);
            lazy[node] = 0n;
        }
    }
    function update(node, l, r, ql, qr, v) {
        if (ql <= l && r <= qr) {
            apply(node, l, r, v);
            return;
        }
        push_down(node, l, r);
        const mid = Math.floor((l + r) / 2);
        if (ql <= mid) update(2 * node, l, mid, ql, qr, v);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr, v);
        tree_sum[node] = (tree_sum[2 * node] + tree_sum[2 * node + 1]) % MOD;
        tree_sq[node] = (tree_sq[2 * node] + tree_sq[2 * node + 1]) % MOD;
    }

    const last_seen = new Map();
    let total = 0n;
    for (let r = 0; r < n; r++) {
        const l = last_seen.has(nums[r]) ? last_seen.get(nums[r]) + 1 : 0;
        update(1, 0, n - 1, l, r, 1n);
        total = (total + tree_sq[1]) % MOD;
        last_seen.set(nums[r], r);
    }
    return Number(total);
};
